import { IReelSpeedConfig } from '../../../types';
export class SpinProfileAction {

    private _stopReel: number | number[] = 0;
    private _reelSpeed: number | number[] | IReelSpeedConfig = 0;
    private _delay: number = 0;

    constructor(stopReel: number | number[], reelSpeed: number | number[] | IReelSpeedConfig, delay: number) {
        this._stopReel = stopReel;
        this._reelSpeed = reelSpeed;
        this._delay = delay;
    }

    public get stopReel(): number | number[] {
        return this._stopReel;
    }

    public get reelSpeed(): number | number[] | IReelSpeedConfig {
        return this._reelSpeed;
    }

    public get delay(): number {
        return this._delay;
    }
}
